-- Backup generated on 2026-10-25 20:34:11

CREATE OR REPLACE PROCEDURE public.sp_update_invoice(IN p_id uuid, IN p_tenant_id uuid, IN p_subtotal numeric, IN p_discount_amount numeric, IN p_tax_amount numeric, IN p_total_amount numeric, IN p_amount_paid numeric, IN p_status character varying, IN p_issue_date timestamp with time zone, IN p_due_date timestamp with time zone, IN p_paid_at timestamp with time zone, IN p_published_at timestamp with time zone, IN p_published_by character varying, IN p_voided_at timestamp with time zone, IN p_voided_by character varying, IN p_void_reason text, IN p_description text, IN p_notes text, IN p_payment_instructions text, IN p_billing_contact_email character varying, IN p_document_storage_key character varying, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE invoices SET         subtotal = p_subtotal,         discount_amount = p_discount_amount,         tax_amount = p_tax_amount,         total_amount = p_total_amount,         amount_paid = p_amount_paid,         status = p_status,         issue_date = p_issue_date,         due_date = p_due_date,         paid_at = p_paid_at,         published_at = p_published_at,         published_by = p_published_by,         voided_at = p_voided_at,         voided_by = p_voided_by,         void_reason = p_void_reason,         description = p_description,         notes = p_notes,         payment_instructions = p_payment_instructions,         billing_contact_email = p_billing_contact_email,         document_storage_key = p_document_storage_key,         updated_at = p_updated_at     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
